  //----
  // spellchecker: ignore-next-line
  administrator discussion_board_administrators @relation(fields: [discussion_board_administrator_id], references: [id], onDelete: Cascade, map: "discussion_board_administrator_sessions_discussion_boa_e71e1029")

  //----
