schemas.schema-02-sections.prisma:
/// Organizational containers for grouping articles by topic within the
/// discussion board.
///
/// Sections serve as the primary categorization mechanism for articles,
/// allowing users to browse content by subject matter (e.g., Politics,
/// Economy, Current Affairs). Each section has a unique name and optional
/// description that explains its purpose and scope.
///
/// **Management**: Sections are created, edited, and deleted exclusively by
/// administrators. Regular users and guests can only view sections and
/// browse articles within them.
///
/// **Relationships**:
/// - One-to-many with {@link discussion_board_articles}: Each section can
/// contain multiple articles, and each article belongs to exactly one
/// section.
/// - Managed by {@link discussion_board_administrators}: Only administrators
/// have permission to modify sections.
///
/// **Business Rules**:
/// - Section names must be unique across the entire board to prevent confusion.
/// - Sections cannot be deleted if they contain articles (referential
/// integrity).
/// - Section modifications are tracked in {@link
/// discussion_board_section_snapshots} for audit purposes.
/// - Soft delete is supported via `deleted_at` field to preserve historical
/// data.
///
/// @namespace Sections
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique name of the section used for identification and display. Must be
  /// distinct from all other sections.
  name String

  /// Optional description explaining the section's purpose, scope, and
  /// guidelines for content.
  description String?

  /// Timestamp when the section was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the section was last modified.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the section was soft deleted. Null indicates the section
  /// is active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  snapshots discussion_board_section_snapshots[]
  articles discussion_board_articles[]
  articleSnapshots discussion_board_article_snapshots[]

  //----
  // INDEXES
  //----
  @@unique([name])
  @@index([created_at])
}

/// Point-in-time snapshots of section modifications for audit trail and
/// revision history.
///
/// This table captures the complete state of a section at the moment of
/// modification, preserving historical data for compliance and audit
/// requirements. Each record represents a specific version of a section,
/// enabling version control, change tracking, and historical analysis of
/// section configurations.
///
/// Key characteristics:
/// - Immutable records: Once created, snapshots are append-only to maintain
/// an accurate audit trail
/// - Complete state capture: All section properties are denormalized to
/// preserve exact historical state
/// - Reference model: {@link discussion_board_sections}
///
/// Temporal field semantics:
/// - section_created_at: When the original section was created (from parent)
/// - section_updated_at: When the section was last modified before this
/// snapshot (from parent)
/// - created_at: When this snapshot was taken
///
/// @namespace Sections
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_section_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the section being snapshot. {@link
  /// discussion_board_sections.id}
  discussion_board_sections_id String @db.Uuid

  /// Name of the section at the time of snapshot.
  name String

  /// Description of the section at the time of snapshot.
  description String?

  /// Timestamp when the original section was created (captured from parent).
  section_created_at DateTime @db.Timestamptz

  /// Timestamp when the section was last modified before this snapshot
  /// (captured from parent).
  section_updated_at DateTime @db.Timestamptz

  /// Timestamp when this snapshot was created.
  created_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  // spellchecker: ignore-next-line
  section discussion_board_sections @relation(fields: [discussion_board_sections_id], references: [id], onDelete: Cascade, map: "discussion_board_section_snapshots_discussion_board_se_83bb5f18")

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([discussion_board_sections_id, created_at], map: "discussion_board_section_snapshots_discussion_board_se_45627c08")
}

schemas.schema-03-articles.prisma:
/// Main entity storing article content for the discussion board platform.
///
/// Articles are the primary content units that users create, organize by
/// sections, and engage with through comments. Each article contains a title
/// and full text content, belongs to exactly one section, and is authored by
/// a registered member.
///
/// Key relationships:
/// - Belongs to a {@link discussion_board_sections} for organizational
/// categorization
/// - Owned by a {@link discussion_board_members} who created it
/// - Created through a {@link discussion_board_member_sessions} for audit trail
/// - Has many {@link discussion_board_comments} (handled in Comments component)
/// - Has many attachments (handled in Attachments component)
/// - Has many {@link discussion_board_tags} via junction table (handled in
/// Tags component)
///
/// Articles support soft deletion to preserve historical data while removing
/// from active listings. Administrators can delete any article regardless of
/// authorship for content moderation purposes.
///
/// @namespace Articles
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_articles {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged section's {@link discussion_board_sections.id}. Every article
  /// must be assigned to exactly one section for organizational
  /// categorization.
  discussion_board_section_id String @db.Uuid

  /// Author member's {@link discussion_board_members.id}. Tracks which
  /// registered user created and owns this article.
  discussion_board_member_id String @db.Uuid

  /// Creation session's {@link discussion_board_member_sessions.id}. Records
  /// the authentication session used when creating the article for audit
  /// purposes.
  discussion_board_member_session_id String @db.Uuid

  /// Article title. Required field that identifies the article in listings and
  /// search results.
  title String

  /// Full text content of the article. Required field containing the main body
  /// text.
  content String

  /// Timestamp when the article was first created. Used for chronological
  /// sorting and display.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the article was last modified. Updated on every edit
  /// operation.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the article was soft-deleted. Null indicates the article
  /// is active. Used for soft deletion to preserve historical data.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  section discussion_board_sections @relation(fields: [discussion_board_section_id], references: [id], onDelete: Cascade)
  author discussion_board_members @relation(fields: [discussion_board_member_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  creationSession discussion_board_member_sessions @relation(fields: [discussion_board_member_session_id], references: [id], onDelete: Cascade, map: "discussion_board_articles_discussion_board_member_sess_66a635f0")

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  snapshots discussion_board_article_snapshots[]
  views discussion_board_article_views[]
  comments discussion_board_comments[]
  articleTags discussion_board_article_tags[]

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([discussion_board_member_session_id], map: "discussion_board_articles_discussion_board_member_sess_6b82e9c5")
  // spellchecker: ignore-next-line
  @@index([discussion_board_section_id, created_at], map: "discussion_board_articles_discussion_board_section_id__cb7d94c3")
  // spellchecker: ignore-next-line
  @@index([discussion_board_member_id, created_at], map: "discussion_board_articles_discussion_board_member_id_c_f434e708")
  @@index([deleted_at, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([content(ops: raw("gin_trgm_ops"))], type: Gin)
