    TestValidator.predicate(
      "banned_at is after from date",
      bannedAt >= yesterday,
    );
    TestValidator.predicate(
      "banned_at is before to date",
      bannedAt <= tomorrow,
    );
  }
  // 8. Test text search on ban_reason
  const searchTerm = "violation";
