  const bannedAdmin =
    retrievedBanRecord.bannedUser as IDiscussionBoardAdministrator.ISummary;
  TestValidator.equals(
    "bannedUser id matches regular admin",
    bannedAdmin.id,
    regularAdmin.id,
  );
  TestValidator.equals(
    "bannedUser email matches regular admin",
    bannedAdmin.email,
    regularAdmin.email,
  );
  TestValidator.equals(
    "bannedUser grade is regular",
    bannedAdmin.grade,
