}): Promise<IDiscussionBoardSection> {
  // Find the section by id (must exist and not be soft deleted)
  const section =
    await MyGlobal.prisma.discussion_board_sections.findUniqueOrThrow({
      where: {
        id: props.sectionId,
        deleted_at: null,
      },
    });
