import { IDiscussionBoardArticleTag } from "../../../../api/structures/IDiscussionBoardArticleTag";
import { patchDiscussionBoardArticlesArticleIdTags } from "../../../../providers/patchDiscussionBoardArticlesArticleIdTags";

@Controller("/discussionBoard/articles/:articleId/tags")
export class DiscussionboardArticlesTagsController {
  /**
   * Update tag assignments for a specific article in the discussion board.
   *
   * This operation allows article owners to manage the tags associated with their articles. Tags are free-text labels used for categorization, filtering, and content discovery across the discussion board platform. Article owners can add new tags, remove existing tags, or modify the complete set of tags assigned to their article.
   *
   * Tags are stored as independent entities in the discussion_board_tags table and linked to articles through the discussion_board_article_tags junction table. Each tag assignment is tracked with a creation timestamp. The system enforces a composite unique constraint preventing the same tag from being assigned to an article multiple times.
   *
   * Security: Only the article's author (owner) can modify tag assignments. The system validates ownership by comparing the authenticated user's member ID with the article's discussion_board_member_id field. Attempts to modify tags on articles owned by other users are rejected with a 403 Forbidden response.
   *
   * Related operations: Use GET /articles/{articleId} to view article details including current tags. Use PATCH /articles to search and filter articles by tags. Tags enable cross-section content discovery and organization.
   *
   * @param connection
   * @param articleId UUID of the target article whose tags will be updated
   * @param body Tag update operations including tags to add and remove
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor null
   * @x-autobe-specification Validate article ownership by checking if authenticated user's member ID matches discussion_board_member_id in discussion_board_articles table.
   *
   * For tag updates:
   * 1. Parse request body to identify tags to add (tag names) and tags to remove (tag IDs)
   * 2. For each tag to add:
   *    - Check if tag exists in discussion_board_tags by name
   *    - If not exists, create new tag record with current timestamp
   *    - Insert new record into discussion_board_article_tags linking article and tag
   *    - Handle composite unique constraint violation (tag already assigned)
   * 3. For each tag to remove:
   *    - Delete corresponding record from discussion_board_article_tags
   *    - Verify record exists before deletion
   * 4. Return updated list of tags assigned to the article
   *
   * Transaction: Wrap all operations in database transaction to ensure atomicity.
   *
   * Error handling:
   * - 404 if article not found or already deleted (deleted_at is not null)
   * - 403 if user is not the article owner
   * - 400 if request body is invalid or empty tag names provided
   * - 409 if tag assignment already exists (handled gracefully)
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async updateTags(
    @TypedParam("articleId")
    articleId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IDiscussionBoardArticleTag.IUpdate,
  ): Promise<IDiscussionBoardArticleTag> {
    try {
      return await patchDiscussionBoardArticlesArticleIdTags({
        articleId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

